// Keeps the events of this recipe, then builds the request(s) for Slack.
const WANTED = ["member.joined", "membership.started", "live.question.created", "support.ticket.created"]
const out = []
for (const item of $input.all()) {
  const msg = item.json.body ?? item.json
  if (WANTED.length && !WANTED.includes(msg.event)) continue
  const SLACK_WEBHOOK = 'https://hooks.slack.com/services/XXX/YYY/ZZZ' // Slack incoming webhook
  const d = msg.data, who = d.user?.name ?? 'Someone'
  const text = {
    'member.joined': `:wave: ${who} joined *${msg.space.slug}*`,
    'membership.started': `:moneybag: ${who} paid ${(d.membership?.amountCents ?? 0) / 100} ${(d.membership?.currency ?? '').toUpperCase()} to join *${msg.space.slug}*`,
    'live.question.created': `:raising_hand: Question in “${d.session?.title}”: ${d.question?.text}`,
    'support.ticket.created': `:ticket: Ticket #${d.ticket?.number}: ${d.ticket?.subject}`,
  }[msg.event]
  if (text) out.push({ json: { method: 'POST', url: SLACK_WEBHOOK, body: { text } } })
}
return out
